use previus_workspace::{Calculation,ManualLink};
use previus_workspace::link_review::{LinkSnapshot,LinkChange,LinkSourceReview,validate_source_links};
fn case()->Calculation{
    let mut source=previus_cnis::import_text("CNIS\nCompetência Remuneração Indicadores\n01/2020 100,00").unwrap();
    source.links.push(previus_cnis::EmploymentLink{sequence:1,raw_employer:Some("EMPREGADOR FICTICIO".into()),affiliation:None,start_date:Some("2020-01-01".into()),end_date:None,reported_last_salary_month:None,inferred_last_salary_end:None,prpps:true,indicators:vec!["PRPPS".into()],validation_status:previus_cnis::ValidationStatus::UnresolvedPrpps,excluded_from_validated_domain:true,source:previus_cnis::SourceRef{page:1,line:1,index:1,byte_offset:0}});
    let initial=LinkSnapshot{employer:"EMPREGADOR FICTICIO".into(),start_date:"2020-01-01".into(),end_date:String::new(),regime:"RPPS".into(),indicators:"PRPPS".into(),confirmed:false,excluded:false};let after=LinkSnapshot{end_date:"2020-12-31".into(),..initial.clone()};
    let review=LinkSourceReview{sequence:1,source_sha256:source.metadata.source_sha256.clone(),excluded:false,history:vec![LinkChange{at:"2026-10-13T10:00:00Z".into(),reason:"Documento fictício".into(),before:initial,after:after.clone()}]};
    Calculation{cnis:Some(source),manual_links:vec![ManualLink{id:1,employer:after.employer,start_date:after.start_date,end_date:after.end_date,regime:after.regime,indicators:after.indicators,confirmed:false,source_review:Some(review)}],..Default::default()}
}
#[test]fn edit_has_linked_history_and_source_end_remains_absent(){let c=case();validate_source_links(&c).unwrap();assert!(c.cnis.as_ref().unwrap().links[0].end_date.is_none());assert_eq!(c.manual_links[0].end_date,"2020-12-31");let loaded:Calculation=serde_json::from_str(&serde_json::to_string(&c).unwrap()).unwrap();validate_source_links(&loaded).unwrap();}
#[test]fn changed_fields_or_original_dates_without_history_are_rejected(){let mut c=case();c.manual_links[0].end_date="2021-01-01".into();assert!(validate_source_links(&c).is_err());let mut c=case();c.manual_links[0].source_review.as_mut().unwrap().history[0].before.end_date="2020-01-01".into();assert!(validate_source_links(&c).is_err());}
#[test]fn wrong_hash_duplicate_source_and_missing_evidence_are_rejected(){let mut c=case();c.manual_links[0].source_review.as_mut().unwrap().source_sha256=Some("f".repeat(64));assert!(validate_source_links(&c).is_err());let mut c=case();c.manual_links.push(c.manual_links[0].clone());assert!(validate_source_links(&c).is_err());let mut c=case();c.manual_links[0].source_review.as_mut().unwrap().history[0].reason.clear();assert!(validate_source_links(&c).is_err());}
#[test]fn editing_regime_does_not_prove_ctc_for_original_prpps(){let mut c=case();let link=&mut c.manual_links[0];link.regime="RGPS".into();link.indicators.clear();link.confirmed=true;let after=&mut link.source_review.as_mut().unwrap().history[0].after;after.regime="RGPS".into();after.indicators.clear();after.confirmed=true;validate_source_links(&c).unwrap();}
#[test]fn legacy_manual_link_defaults_to_no_source_review(){let json=serde_json::json!({"id":1,"employer":"FICTICIO","start_date":"","end_date":"","regime":"A confirmar","indicators":"","confirmed":false});let link:ManualLink=serde_json::from_value(json).unwrap();assert!(link.source_review.is_none());}
